package org.example.like;

import org.example.auth.AuthenticatedMember;
import org.example.post.PostDetailRow;
import org.example.post.PostNotFoundException;
import org.example.post.PostVisibilityMapper;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

// 관계 행과 비정규화 좋아요 수를 함께 쓴다.
@Service
public class MyBatisLikeService {
    private final PostVisibilityMapper visiblePosts;
    private final MyBatisLikeMapper likes;

    public MyBatisLikeService(PostVisibilityMapper visiblePosts, MyBatisLikeMapper likes) {
        this.visiblePosts = visiblePosts;
        this.likes = likes;
    }

    @Transactional
    public LikeResponse setLiked(Long postId, AuthenticatedMember me) {
        PostDetailRow post = visiblePosts.findVisibleDetail(postId, me.id(), me.role());
        if (post == null || !"PUBLISHED".equals(likes.findPostStatus(postId)))
            throw new PostNotFoundException();
        if (post.authorId.equals(me.id()))
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "내 글에는 좋아요를 누를 수 없습니다.");
        long count = post.likeCount;
        if (!likes.existsLike(postId, me.id())) {
            likes.insertLike(postId, me.id());
            likes.increaseLikeCount(postId);
            count++;
        }
        return new LikeResponse(postId, true, count);
    }
}

