package org.example.post;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// JPA Statistics는 Mapper SQL을 세지 못하므로 MyBatis Executor에서 SELECT를 센다.
@SpringBootTest
@AutoConfigureMockMvc
class PostListQueryCountTest {
    @Autowired MockMvc mockMvc;
    @Autowired MyBatisStatementCounter counter;

    @Test
    void queryCountDoesNotGrowWithPageSize() throws Exception {
        counter.clear();
        mockMvc.perform(get("/api/boards/free/posts").param("size", "5"))
                .andExpect(status().isOk());
        long countForSize5 = counter.getCount();

        counter.clear();
        mockMvc.perform(get("/api/boards/free/posts").param("size", "20"))
                .andExpect(status().isOk());
        long countForSize20 = counter.getCount();

        System.out.printf("MyBatis SELECT count: size=5 %d, size=20 %d%n", countForSize5, countForSize20);
        assertTrue(countForSize5 > 0, "Mapper SELECT가 실제로 계측되어야 한다");
        assertEquals(countForSize5, countForSize20,
                "글 수가 늘어도 SELECT 문장 수가 증가하지 않아야 한다");
        assertTrue(countForSize5 <= 5, "목록·COUNT·태그 SQL이 5개 이하여야 한다");
    }
}

